tools.example:
c1 = Simulink.BlockDiagram.getChecksum('myModel');
set_param('myModel/Gain', 'Position', [100 100 140 130]);
c2 = Simulink.BlockDiagram.getChecksum('myModel');
isequal(c1, c2)   % true: layout changes do not affect the checksum

opts = Simulink.FindOptions('SearchDepth', 1);
h = Simulink.findBlocks('vdp', 'BlockType', 'Gain', opts);
getfullname(h)

sid = Simulink.ID.getSID('vdp/Mu')     % e.g. 'vdp:3'
h = Simulink.ID.getHandle(sid);
hilite_system(h);

simIn = Simulink.SimulationInput('myModel');
simIn = simIn.setVariable('Kp', 2.5);
simIn = simIn.setVariable('Ts', 1e-3, 'Workspace', 'myModel');
out = sim(simIn);

simIn = Simulink.SimulationInput('myModel');
simIn = simIn.setModelParameter('StopTime', '50', 'SimulationMode', 'accelerator');
out = sim(simIn);

t = (0:0.01:10)';
ds = Simulink.SimulationData.Dataset;
ds = ds.addElement(timeseries(sin(t), t), 'u');
simIn = Simulink.SimulationInput('myModel');
simIn = simIn.setExternalInput(ds);
out = sim(simIn);

out1 = sim('myModel', 'SaveFinalState', 'on', 'SaveOperatingPoint', 'on', 'FinalStateName', 'xFinal', 'StopTime', '100');
simIn = Simulink.SimulationInput('myModel');
simIn = simIn.setInitialState(out1.xFinal);
simIn = simIn.setModelParameter('StopTime', '200');
out2 = sim(simIn);

simIn = simIn.setPostSimFcn(@(o) struct('peak', max(o.logsout.get('y').Values.Data)));
out = parsim(simIn);
peaks = arrayfun(@(o) o.peak, out);

simIn(1:20) = Simulink.SimulationInput('myModel');
for k = 1:20, simIn(k) = simIn(k).setVariable('Kp', k/10); end
job = batchsim(parcluster('local'), simIn, 'Pool', 4);
wait(job);
out = fetchOutputs(job);

e1 = Simulink.BusElement; e1.Name = 'speed'; e1.DataType = 'double';
e2 = Simulink.BusElement; e2.Name = 'gear';  e2.DataType = 'int8';
VehicleBus = Simulink.Bus; VehicleBus.Elements = [e1 e2];
set_param('m/In1', 'OutDataTypeStr', 'Bus: VehicleBus');

speed = Simulink.Signal;
speed.DataType = 'single'; speed.CoderInfo.StorageClass = 'ExportedGlobal';
ph = get_param('m/Plant', 'PortHandles');
set_param(ph.Outport(1), 'Name', 'speed', 'MustResolveToSignalObject', 'on');

Kp = Simulink.Parameter(2.5);
Kp.DataType = 'single'; Kp.Min = 0; Kp.Max = 10;
Kp.CoderInfo.StorageClass = 'ExportedGlobal';
set_param('m/Gain', 'Gain', 'Kp');

Q8 = fixdt(1, 16, 8);          % Simulink.NumericType
Q8.IsAlias = true;
set_param('m/Conv', 'OutDataTypeStr', 'Q8');

LUT = Simulink.LookupTable;
LUT.Table.Value = [0 1 4 9 16];
LUT.Breakpoints(1).Value = 0:4;
set_param('m/1-D Lookup Table', 'DataSpecification', 'Lookup table object', 'LookupTableObject', 'LUT');

dd = Simulink.data.dictionary.create('project.sldd');
sec = getSection(dd, 'Design Data');
addEntry(sec, 'Kp', Simulink.Parameter(2));
saveChanges(dd);
set_param('myModel', 'DataDictionary', 'project.sldd');

dd = Simulink.data.dictionary.open('project.sldd');
sec = getSection(dd, 'Design Data');
e = getEntry(sec, 'Kp');
p = getValue(e); p.Value = 3; setValue(e, p);
saveChanges(dd); close(dd);

MassVC = Simulink.VariantControl('Value', 1, 'ActivationTime', 'update diagram');
Mass = Simulink.VariantVariable('Choices', {'MassVC==1', 1200, 'MassVC==2', 1800});
set_param('m/Gain', 'Gain', 'Mass');

cs = copy(getActiveConfigSet('ref'));
cs.Name = 'FixedStep1ms';
set_param(cs, 'SolverType', 'Fixed-step', 'FixedStep', '0.001');
attachConfigSet('newModel', cs, true);
setActiveConfigSet('newModel', 'FixedStep1ms');

attachConfigSet('myModel', csCodegen, true);
setActiveConfigSet('myModel', csCodegen.Name);
slbuild('myModel');

sim('vdp');
run = Simulink.sdi.Run.getLatest;
run.Name = 'baseline';
sig = getSignalByIndex(run, 1);
plot(sig.Values);
